def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    fill = counts.most_common(1)[0][0]

    # Identify the repeated separator rows and columns. Their dominant color
    # differs from the interior fill color.
    def dominant(values):
        c = Counter(values)
        color, n = c.most_common(1)[0]
        return color, n / len(values)

    row_lines = []
    for r in range(h):
        color, frac = dominant(grid[r])
        if color != fill and frac >= 0.60:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        color, frac = dominant([grid[r][c] for r in range(h)])
        if color != fill and frac >= 0.60:
            col_lines.append(c)

    # Keep the regularly spaced lattice locations, dropping its final
    # boundary, which is not part of the encoded output.
    def regular(lines):
        if len(lines) < 2:
            return lines
        gaps = [b - a for a, b in zip(lines, lines[1:])]
        step = Counter(gaps).most_common(1)[0][0]
        return [x for x in lines if not lines or
                all((x - lines[0]) % step == 0)]

    row_lines = regular(row_lines)
    col_lines = regular(col_lines)

    if len(row_lines) > 1:
        row_lines = row_lines[:-1]
    if len(col_lines) > 1:
        col_lines = col_lines[:-1]

    # Use the marker at each separator crossing; ordinary separator color
    # is replaced by the interior fill color.
    out = []
    for r in row_lines:
        row = []
        for c in col_lines:
            value = grid[r][c]
            if value not in (fill,):
                row.append(value)
            else:
                row.append(fill)
        out.append(row)
    return out
